#include "Mapper222.h"
#include "../state_io.h"
#include <algorithm>
void Mapper222::reset(){uint16_t pc=std::max<uint16_t>(1,uint16_t(prgBanks*2u));prg8[0]=prg8[1]=0;prg8[2]=pc>1?uint16_t(pc-2):0;prg8[3]=uint16_t(pc-1);for(int i=0;i<8;i++)chr1[i]=0;irqCounter=0;mirrorMode=1;a12Low=0;lastA12=irqActive=false;}
bool Mapper222::cpuMapRead(uint16_t a,uint32_t&m){if(a<0x8000)return false;uint16_t c=std::max<uint16_t>(1,uint16_t(prgBanks*2u));uint8_t s=uint8_t((a-0x8000)>>13);m=uint32_t(prg8[s]%c)*0x2000u+(a&0x1FFFu);return true;}
bool Mapper222::cpuMapWrite(uint16_t a,uint32_t&m,uint8_t d){if(a<0x8000)return false;switch(a&0xF003u){case 0x8000:prg8[0]=d;break;case 0x9000:mirrorMode=(d&1u)?0u:1u;break;case 0xA000:prg8[1]=d;break;case 0xB000:chr1[0]=d;break;case 0xB002:chr1[1]=d;break;case 0xC000:chr1[2]=d;break;case 0xC002:chr1[3]=d;break;case 0xD000:chr1[4]=d;break;case 0xD002:chr1[5]=d;break;case 0xE000:chr1[6]=d;break;case 0xE002:chr1[7]=d;break;case 0xF000:irqCounter=d;irqActive=false;break;default:break;}m=0;return true;}
bool Mapper222::ppuMapRead(uint16_t a,uint32_t&m){if(a>0x1FFF)return false;uint16_t c=std::max<uint16_t>(1,uint16_t(chrBanks?chrBanks*8u:8u));uint8_t s=uint8_t(a>>10);m=uint32_t(chr1[s]%c)*0x400u+(a&0x3FFu);return true;}bool Mapper222::ppuMapWrite(uint16_t a,uint32_t&m,uint8_t){return chrBanks==0&&ppuMapRead(a,m);}
void Mapper222::ppuAddressBus(uint16_t a){bool hi=(a&0x1000u)!=0;if(!hi){if(a12Low<0xFF)++a12Low;}else{if(!lastA12&&a12Low>=8&&irqCounter){++irqCounter;if(irqCounter>=240){irqCounter=0;irqActive=true;}}a12Low=0;}lastA12=hi;}
void Mapper222::saveState(std::vector<uint8_t>&o)const{using namespace ciphernes_state;for(uint16_t v:prg8)write_u16(o,v);for(uint16_t v:chr1)write_u16(o,v);write_u16(o,irqCounter);write_u8(o,mirrorMode);write_u8(o,a12Low);write_bool(o,lastA12);write_bool(o,irqActive);}bool Mapper222::loadState(const uint8_t*&p,const uint8_t*e){using namespace ciphernes_state;for(uint16_t&v:prg8)if(!read_u16(p,e,v))return false;for(uint16_t&v:chr1)if(!read_u16(p,e,v))return false;return read_u16(p,e,irqCounter)&&read_u8(p,e,mirrorMode)&&read_u8(p,e,a12Low)&&read_bool(p,e,lastA12)&&read_bool(p,e,irqActive);}
